import{_ as r,a0 as n,w as p,s,ao as m,I as o,a1 as a,A as i,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse(`{"title":"15 个‘ls’命令的面试问题（一） | LCTT x X-CMD","titleTemplate":false,"description":"15 个‘ls’命令的面试问题（一） | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"15 个‘ls’命令的面试问题（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"15 个‘ls’命令的面试问题（一） | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150309 15 Interview Questions on Linux 'ls ' Command--Part 1","title":"15 个‘ls’命令的面试问题（一）","tag":"201504","desc":""},"relativePath":"201504/20150309 15 Interview Questions on Linux 'ls ' Command--Part 1.md","filePath":"[post].md"}`),c={name:"201504/20150309 15 Interview Questions on Linux 'ls ' Command--Part 1.md"};function d(h,e,u,w,f,x){const l=n("Link");return p(),s("div",null,[e[15]||(e[15]=m(`<h1 id="_15-个-ls-命令的面试问题-一" tabindex="-1">15 个‘ls’命令的面试问题（一） <a class="header-anchor" href="#_15-个-ls-命令的面试问题-一" aria-label="Permalink to “15 个‘ls’命令的面试问题（一）”">​</a></h1><p>Unix或类Unix系统中的“文件列表”命令“ls”是最基础并且使用的最广泛的命令行中工具之一。它是一个POSIX兼容工具，在GNU基本工具集以及BSD各种变体上都可以使用。“ls”命令可以结合大量的选项来达到想要的结果。</p><p>这篇文章的目的在于通过相关的样例来深入讨论文件列表命令。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/ls-Command-Questions.png" alt="15 ls Command Questions"></p><p><em>15个“ls”命令问题。</em></p><h3 id="_1-如何列出目录中的文件" tabindex="-1">1. 如何列出目录中的文件？### <a class="header-anchor" href="#_1-如何列出目录中的文件" aria-label="Permalink to “1. 如何列出目录中的文件？###”">​</a></h3><p>答：linux文件列表命令“ls”就是干这个的。</p><pre><code># ls
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-files.gif" alt="List Files"></p><p><em>列出文件</em></p><p>同时，我们也可以使用“echo(回显)”命令与一个通配符(*)参数来雷锤目录中的所有文件。</p><pre><code># echo *
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-all-files.gif" alt="List All Files"></p><p><em>列出所有的文件。</em></p><h3 id="_2-如何只使用echo命令来只列出所有目录" tabindex="-1">2. 如何只使用echo命令来只列出所有目录？### <a class="header-anchor" href="#_2-如何只使用echo命令来只列出所有目录" aria-label="Permalink to “2. 如何只使用echo命令来只列出所有目录？###”">​</a></h3><pre><code># echo */
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-all-directories.gif" alt="List All Directories"></p><p><em>列出所有的目录</em></p><h3 id="_3-怎样列出一个目录中的所有文件-包括隐藏的以-开头的文件" tabindex="-1">3. 怎样列出一个目录中的所有文件， 包括隐藏的以“.”开头的文件？### <a class="header-anchor" href="#_3-怎样列出一个目录中的所有文件-包括隐藏的以-开头的文件" aria-label="Permalink to “3.  怎样列出一个目录中的所有文件， 包括隐藏的以“.”开头的文件？###”">​</a></h3><p>答：我们需要将“-a”选项与“ls”命令一起使用。</p><pre><code># ls -a
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-all-hidden-files.gif" alt="List All Hidden Files"></p><p><em>列出所有的隐藏文件。</em></p><h3 id="_4-如何列出目录中除了-当前目录-和-父目录-之外的所有文件-包括隐藏文件" tabindex="-1">4. 如何列出目录中除了 “当前目录 .”和“父目录 ..”之外的所有文件，包括隐藏文件？### <a class="header-anchor" href="#_4-如何列出目录中除了-当前目录-和-父目录-之外的所有文件-包括隐藏文件" aria-label="Permalink to “4. 如何列出目录中除了 “当前目录 .”和“父目录 ..”之外的所有文件，包括隐藏文件？###”">​</a></h3><p>答： 我们需要将“-A”选项与“ls”命令一起使用</p><pre><code># ls -A
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Do-not-list-Implied.gif" alt="Do Not List Implied"></p><p><em>别列出指代当前目录和父目录的文件</em></p><h3 id="_5-如何使用长格式打印出当前目录内容" tabindex="-1">5. 如何使用长格式打印出当前目录内容？### <a class="header-anchor" href="#_5-如何使用长格式打印出当前目录内容" aria-label="Permalink to “5. 如何使用长格式打印出当前目录内容？###”">​</a></h3><p>答： 我们需要将“-l”选项与“ls”命令一起使用。</p><pre><code># ls -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-files-long.gif" alt="List Files Long"></p><p><em>列出文件的长格式。</em></p><p>上面的样例中，其输出结果看起来向下面这样。</p><pre><code>drwxr-xr-x  5 avi tecmint      4096 Sep 30 11:31 Binary
</code></pre><p>上面的drwxr-xr-x 是文件的权限，分别代表了文件所有者，所属组以及“整个世界”。 所有者具有读(r),写(w)以及执行(x)等权限。 该文件所属组具有读(r)和执行(x)但是没有写的权限，整个世界的其他可以访问到该文件的人也具有相同权限。</p><ul><li>开头的‘d’意味着这是一个目录</li><li>数字&#39;5&#39;表示符号链接（有5个符号链接）</li><li>文件 Binary归属于用户 “avi”以及用户组 &quot;tecmint&quot;</li><li>Sep 30 11:31 表示文件最后一次的访问日期与时间。</li></ul><h3 id="_6-假如让你来将目录中的内容以长格式列表打印-并且显示出隐藏的-点文件-你会如何实现" tabindex="-1">6. 假如让你来将目录中的内容以长格式列表打印，并且显示出隐藏的“点文件”，你会如何实现？### <a class="header-anchor" href="#_6-假如让你来将目录中的内容以长格式列表打印-并且显示出隐藏的-点文件-你会如何实现" aria-label="Permalink to “6. 假如让你来将目录中的内容以长格式列表打印，并且显示出隐藏的“点文件”，你会如何实现？###”">​</a></h3><p>答： 我们需要同时将&quot;-a&quot;和&quot;-l&quot;选项与“ls”命令一起使用（LCTT 译注：单字符选项可以合并写）。</p><pre><code># ls -la
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Print-Content-of-Directory.gif" alt="Print Content of Directory"></p><p><em>打印目录内容</em></p><p>此外，如果我们不想列出“当前目录”和&quot;父目录&quot;，可以将“-A”和“-l”选项同“ls”命令一起使用。</p><pre><code># ls -lA
</code></pre><h3 id="_7-如何找到每个文件的创建者" tabindex="-1">7. 如何找到每个文件的创建者？### <a class="header-anchor" href="#_7-如何找到每个文件的创建者" aria-label="Permalink to “7. 如何找到每个文件的创建者？###”">​</a></h3><p>答： 我们需要结合 “--author”和 &quot;-l&quot;选项来打印出每个文件的创建者。</p><pre><code># ls --author -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-Author-Files.gif" alt="List Author Files"></p><p><em>列出文件创建者。</em></p><h3 id="_8-如何对用转义字符打印出非显示字符" tabindex="-1">8. 如何对用转义字符打印出非显示字符？### <a class="header-anchor" href="#_8-如何对用转义字符打印出非显示字符" aria-label="Permalink to “8. 如何对用转义字符打印出非显示字符？###”">​</a></h3><p>答：我们只需要使用“-b”选项来对非显示字符进行转义打印</p><pre><code># ls -b
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Print-Escape-Character.gif" alt="Print Escape Character"></p><h3 id="_9-用指定特定的单位格式来列出文件和目录的大小-你会如何实现" tabindex="-1">9. 用指定特定的单位格式来列出文件和目录的大小，你会如何实现？### <a class="header-anchor" href="#_9-用指定特定的单位格式来列出文件和目录的大小-你会如何实现" aria-label="Permalink to “9. 用指定特定的单位格式来列出文件和目录的大小，你会如何实现？###”">​</a></h3><p>答： 在此可以同时使用选项“-block-size=scale”和“-l”，但是我们需要用特定的单位如M，K等来替换‘scale’参数。</p><pre><code># ls --block-size=M -l
# ls --block-size=K -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-File-Scale-Format.gif" alt="List File Scale Format"></p><p><em>列出文件大小单位格式。</em></p><h3 id="_10-列出目录中的文件-但是不显示备份文件-即那些文件名以-结尾的文件" tabindex="-1">10. 列出目录中的文件，但是不显示备份文件，即那些文件名以‘~’结尾的文件### <a class="header-anchor" href="#_10-列出目录中的文件-但是不显示备份文件-即那些文件名以-结尾的文件" aria-label="Permalink to “10. 列出目录中的文件，但是不显示备份文件，即那些文件名以‘~’结尾的文件###”">​</a></h3><p>答： 选项‘-B’赶来救驾。</p><pre><code># ls -B
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-File-Without-Backup.gif" alt="List File Without Backup"></p><p><em>列出非备份文件</em></p><h3 id="_11-将目录中的所有文件按照名称进行排序-并显示其最后修改时间信息" tabindex="-1">11. 将目录中的所有文件按照名称进行排序，并显示其最后修改时间信息？### <a class="header-anchor" href="#_11-将目录中的所有文件按照名称进行排序-并显示其最后修改时间信息" aria-label="Permalink to “11. 将目录中的所有文件按照名称进行排序，并显示其最后修改时间信息？###”">​</a></h3><p>答： 为了实现这个需求，我们需要同时将“-c”和&quot;-l&quot;选项与命令一起使用。</p><pre><code># ls -cl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Sort-Files.gif" alt="Sort Files"></p><p><em>文件排序</em></p><h3 id="_12-将目录中的文件按照修改时间进行排序-并显示相关联的信息。" tabindex="-1">12. 将目录中的文件按照修改时间进行排序，并显示相关联的信息。### <a class="header-anchor" href="#_12-将目录中的文件按照修改时间进行排序-并显示相关联的信息。" aria-label="Permalink to “12. 将目录中的文件按照修改时间进行排序，并显示相关联的信息。###”">​</a></h3><p>答： 我们需要同时使用3个选项：&#39;-l&#39;,&#39;-t&#39;,&#39;-c&#39; 来对文件使用修改时间排序，最新的修改时间排在最前。</p><pre><code># ls -ltc
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Sort-Files-by-Modification.gif" alt="Sort Files by Modification"></p><p><em>按照修改时间对文件排序。</em></p><h3 id="_13-如何控制-ls-命令的输出颜色的有无" tabindex="-1">13. 如何控制‘ls’命令的输出颜色的有无？### <a class="header-anchor" href="#_13-如何控制-ls-命令的输出颜色的有无" aria-label="Permalink to “13. 如何控制‘ls’命令的输出颜色的有无？###”">​</a></h3><p>答： 需要使用选项‘--color=parameter’，参数具有三种不同值，“auto(自动)”，“always(一直)”，“never(无色)”。</p><pre><code># ls --color=never
# ls --color=auto
# ls --color=always
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/ls-colorful-output.gif" alt="ls Colorful Output"></p><p><em>ls的输出颜色</em></p><h3 id="_14-假如只需要列出目录本身-而不是目录的内容-你会如何做" tabindex="-1">14. 假如只需要列出目录本身，而不是目录的内容，你会如何做？### <a class="header-anchor" href="#_14-假如只需要列出目录本身-而不是目录的内容-你会如何做" aria-label="Permalink to “14. 假如只需要列出目录本身，而不是目录的内容，你会如何做？###”">​</a></h3><p>答：在此“-d”选项就会显得很顺手。</p><pre><code># ls -d
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-Directory-Entries.gif" alt="List Directory Entries"></p><p><em>列出目录本身</em></p><h3 id="_15-为长格式列表命令-ls-l-创建一个别名-ll-并将其结果输出到一个文件而不是标准输出中。" tabindex="-1">15. 为长格式列表命令&quot;ls -l&quot;创建一个别名“ll”，并将其结果输出到一个文件而不是标准输出中。### <a class="header-anchor" href="#_15-为长格式列表命令-ls-l-创建一个别名-ll-并将其结果输出到一个文件而不是标准输出中。" aria-label="Permalink to “15. 为长格式列表命令ls -l创建一个别名“ll”，并将其结果输出到一个文件而不是标准输出中。###”">​</a></h3><p>答：在上述的这个场景中，我们需要将别名添加到.bashrc文件中，然后使用重定向操作符将输出写入到文件而不是标准输出中。我们将会使用编辑器nano。</p><pre><code># ls -a
# nano .bashrc
# ll &gt;&gt; ll.txt
# nano ll.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Create-ls-Alias.gif" alt="Create Alias for ls command"></p><p><em>为ls命令创建别名。</em></p><p>先到此为止，别忘了在下面的评论中提出你们的宝贵意见，我会再次带着另外的有趣的文章在此闪亮登场。</p><h3 id="参考阅读" tabindex="-1">参考阅读：### <a class="header-anchor" href="#参考阅读" aria-label="Permalink to “参考阅读：###”">​</a></h3>`,90)),o("ul",null,[o("li",null,[a(l,{href:"http://www.tecmint.com/ls-interview-questions/"},{default:i(()=>[...e[0]||(e[0]=[t("10 个‘ls’命令的面试问题（二）",-1)])]),_:1})]),o("li",null,[a(l,{href:"http://linux.cn/article-5109-1.html"},{default:i(()=>[...e[1]||(e[1]=[t("Linux中15个基础的'ls'命令",-1)])]),_:1})])]),e[16]||(e[16]=o("hr",null,null,-1)),o("p",null,[e[3]||(e[3]=t("via: ",-1)),a(l,{href:"http://www.tecmint.com/ls-command-interview-questions/"},{default:i(()=>[...e[2]||(e[2]=[t("http://www.tecmint.com/ls-command-interview-questions/",-1)])]),_:1})]),o("p",null,[e[7]||(e[7]=t("作者：",-1)),a(l,{href:"http://www.tecmint.com/author/avishek/"},{default:i(()=>[...e[4]||(e[4]=[t("Avishek Kumar",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),a(l,{href:"https://github.com/theo-l"},{default:i(()=>[...e[5]||(e[5]=[t("theo-l",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),a(l,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:i(()=>[...e[6]||(e[6]=[t("校对者ID",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创翻译，",-1)),a(l,{href:"http://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const L=r(c,[["render",d]]);export{_ as __pageData,L as default};
